import { LEGAL_ANCHORS, type LegalDocuments, type LegalFacts } from "./types";

/** Translation of the approved Azerbaijani text (20 October 2026). The Azerbaijani version prevails. */
export function enLegalDocuments(f: LegalFacts): LegalDocuments {
  const contactLine = `${f.legalName} · ${f.address} · ${f.securityEmail} · ${f.email} · ${f.phone}`;
  return {
    privacy: {
      title: "Privacy policy",
      metaDescription: "Why Luxe Home Estate collects personal data, who it is shared with, how long it is kept and how you can exercise your rights.",
      description: "How we collect, use and protect your personal data and how you can exercise your rights.",
      updatedAt: "20 October 2026",
      introduction: `This Privacy policy explains for what purpose, on what basis, for how long and how ${f.legalName} (TIN ${f.voen}, address: ${f.address}; brand owner — ${f.ownerName}) processes personal data collected through the luxehomeestate.az website, its subpages, the personal account, the admin panel and the official Telegram bot (together — the "Platform"). It has been prepared in accordance with the Law of the Republic of Azerbaijan "On Personal Data". Please read it carefully before using the Platform; if you do not agree, do not submit any data on the Platform.`,
      sections: [
        { heading: "1. Definitions", bullets: [
          { label: "Personal data —", text: "any information that allows you to be identified directly or indirectly (name, phone, email, IP address, account identifier, etc.)." },
          { label: "Data subject —", text: "the natural person whose personal data is processed, i.e. you." },
          { label: "Owner (data controller) —", text: `the person who determines the purposes and means of processing: ${f.legalName}.` },
          { label: "Operator (processor) —", text: "a service provider that processes data on the owner's instructions and on its behalf." },
          { label: "Processing —", text: "any operation on data, including collection, recording, storage, alteration, use, transfer, blocking and destruction." },
          { label: "Cross-border transfer —", text: "the transfer of data to a server or person located outside the Republic of Azerbaijan." },
          { label: "User —", text: "any visitor of the Platform, registered account holder (user, property owner, agent, agency, corporate account) or person submitting an enquiry." },
        ] },
        { heading: "2. Data owner and contact", bullets: [
          { label: "Owner:", text: `${f.legalName}, TIN ${f.voen}.` },
          { label: "Address:", text: f.address },
          { label: "Personal data requests:", text: `${f.securityEmail} (privacy and security), ${f.email} (general questions), phone ${f.phone}.` },
        ], paragraphs: ["Privacy requests are logged separately and answered within the time limits set out in section 10 of this policy."] },
        { heading: "3. What data we collect", paragraphs: ["We only collect data that is necessary for the stated purpose. Most of it you provide yourself; some is generated automatically when you use the Platform, and some is passed to us by services you choose (for example, Sign in with Google)."] },
        { heading: "3.1. Data you provide", level: 3, bullets: [
          { label: "Account data:", text: "first name, last name, email address, phone number, account type, password (stored only as an irreversible hash — nobody, including our staff, can see the password itself), interface language, optional date of birth (only to check that you are 18 or older), profile photo." },
          { label: "Agent and agency data:", text: "agency name, TIN, office and branch addresses, office phone, WhatsApp, Telegram username, work email, logo and cover image, description, areas of activity, team membership." },
          { label: "Listing data:", text: "the property's address (city, district, settlement, street, building), features, price, description, photos, floor plans, virtual tour link and contact method." },
          { label: "Verification documents:", text: "images of documents you voluntarily upload to verify a listing or account (for example, an ownership extract). These files are not public and are kept in a separate private storage." },
          { label: "Enquiries and requests:", text: "the name, phone, email, subject, message, chosen date and listing you enter in contact, viewing, reservation, open house, valuation, support and report forms." },
          { label: "Report evidence and appeals:", text: "images you attach to a report and the text of an appeal against a moderation decision." },
          { label: "Reviews:", text: "the rating and text you write about an agent or agency." },
          { label: "Preferences:", text: "saved searches, favourite listings, comparison list, notification preferences and quiet hours." },
          { label: "CRM records:", text: "information that agents and agencies enter in their account about their own clients (see 6.3)." },
        ] },
        { heading: "3.2. Automatically collected data", level: 3, bullets: [
          { label: "Technical data:", text: "IP address, browser and operating system, device type, language, request time, page opened, referrer and UTM campaign parameters." },
          { label: "Session and security data:", text: "session identifier, sign-in time, failed sign-in attempts, a record of sign-ins from a new device, a \"known device\" record (browser + operating system label and a salted, irreversible hash of the IP address)." },
          { label: "Statistics:", text: "listing views and clicks on the \"Show number\", WhatsApp and Telegram buttons. To count unique views, the IP address is not used in raw form but as a one-way hash and is deleted after 2 days." },
          { label: "Performance metrics:", text: "page load speed indicators (Core Web Vitals) — not linked to your identity." },
        ] },
        { heading: "3.3. Data received from third parties", level: 3, bullets: [
          { label: "Sign in with Google, Apple, Facebook or Telegram:", text: "the permanent identifier the provider gives you, your name and (if the provider supplies it) your email address and its verification status. Your password, contacts, friends list or messages are not passed to us." },
          { label: "Telegram bot:", text: "your Telegram identifier, chat identifier, username, the commands you send to the bot and support messages." },
          { label: "SMS provider:", text: "the delivery status of the verification code sent." },
        ] },
        { heading: "3.4. Data we do not collect", level: 3, paragraphs: ["We do not collect special categories of data — racial or ethnic origin, religious and political views, health, biometric data, sex life, criminal convictions — and ask you not to enter them on the Platform. Payment card details are not entered or stored on the Platform."] },
        { heading: "4. Purposes and legal bases of processing", table: {
          columns: ["Purpose", "Data", "Legal basis"],
          rows: [
            ["Creating an account, providing sign-in and sessions", "account, session and social sign-in data", "data you provide and your consent; performance of the terms of use"],
            ["Publishing, moderating and displaying listings", "listing, photos, contact method", "performance of the terms of use"],
            ["Delivering your enquiry to the listing owner, agent or our office", "enquiry form", "your consent (by submitting the form)"],
            ["Sending notifications (site, email, browser push, Telegram)", "contact details, preferences", "performance of the service; separate explicit consent for Telegram and push"],
            ["Preventing fake listings, fraud, spam and account takeover", "technical, security and behavioural signals", "legitimate interest in the security of the Platform and its users, and legal obligation"],
            ["Investigating reports, appeals and reviews", "report, evidence, appeal, review", "performance of the terms of use"],
            ["Improving the Platform, keeping statistics", "anonymised and aggregated indicators", "legitimate interest; consent for analytics cookies"],
            ["Meeting legal requirements, protecting our rights in disputes", "necessary records, audit log", "requirement of law"],
          ],
        }, paragraphs: [
          "Before using your data for a new purpose that is not listed in this table and is incompatible with the original purpose, we will inform you and, where necessary, obtain your separate consent.",
          "Automated checks. Before publication, listings pass automatic risk signals (a price sharply below the market, contact details in the text, a photo or text copied from another listing, etc.). A high risk score does not reject a listing — it sends it to a moderator for manual review. The account trust score is likewise only a recommendation to the moderator; restrictions are always decided by a staff member and you can appeal them.",
          "Artificial intelligence features. Search, the photo advisor, automatic SEO text and the Knowledge Hub advisor run on Cloudflare Workers AI. Only listing data and the question you type are passed to these features; your data is not used to train models.",
        ] },
        { heading: "5. Information publicly visible in listings and profiles", bullets: [
          { text: "When a listing is published, its description, price, photos and approximate location are visible to everyone. Whether to show the exact address and building number is your choice." },
          { text: "The name of the person who posted the listing (for an agency listing, the agency's name and logo) is displayed." },
          { text: "Your phone number is not written into the page code — a visitor sees it only after clicking \"Show number\", having passed a rate limit and bot filter. Your email address is not shown publicly." },
          { text: "An approved review, the reviewer's name and the agent's/agency's reply are publicly visible." },
          { text: "Verification documents themselves and their type are never shown publicly — only a badge such as \"Documents verified\" appears." },
        ], paragraphs: ["Listing and profile data may be indexed by search engines. After a listing is deleted, we have no control over old copies in the caches of third-party sites (for example, a search engine)."] },
        { heading: "6. Who we share data with", paragraphs: ["We do not sell or rent your personal data or pass it to third parties for advertising. Data is shared only in the cases below and only to the extent necessary."] },
        { heading: "6.1. Other users of the Platform", level: 3, bullets: [
          { text: "An enquiry you send from a listing page is delivered to whoever posted that listing (property owner, agent or agency)." },
          { text: "An enquiry on an agency listing is seen by an approved member of the agency according to the agency's distribution rule." },
          { text: "When a listing is transferred to another agency, earlier enquiries stay with the previous agency and do not pass to the new one." },
        ] },
        { heading: "6.2. Service providers (operators)", level: 3, table: {
          columns: ["Provider", "Purpose", "Data"],
          rows: [
            ["Cloudflare, Inc. (USA)", "hosting, database (D1), file storage (R2), image processing, CDN, DDoS protection, Turnstile bot check, Web Analytics, Workers AI, vector search", "all Platform data"],
            ["Resend (USA)", "email delivery", "email address, name, message text"],
            ["Telegram (Telegram Messenger Inc. / FZ-LLC)", "bot notifications, Sign in with Telegram", "Telegram ID, notification text"],
            ["Google LLC (USA)", "Sign in with Google; Google Analytics / Tag Manager if you consent", "identifier, name, email; anonymous usage data for analytics"],
            ["Apple Inc. (USA)", "Sign in with Apple", "identifier, name, email (or Apple's private relay address)"],
            ["Meta Platforms Ireland Ltd.", "Facebook Login", "identifier, name, email"],
            ["Geoapify GmbH (Germany)", "converting an address into map coordinates", "listing address (no personal data is sent)"],
            ["SMS provider", "phone sign-in and number verification codes", "phone number, one-time code"],
            ["Browser push services (Google, Mozilla, Apple)", "browser notifications", "push subscription endpoint, notification text"],
          ],
        }, paragraphs: ["Providers may use the data only on our instructions and to deliver their services. Social sign-in providers process your data themselves under their own privacy policies."] },
        { heading: "6.3. CRM data of agents and agencies", level: 3, paragraphs: [`When an agent or agency enters information about its own clients in the "Clients" section of the account, the agent or agency is the owner of that data; in this case ${f.name} acts only as a technical operator. The agency is itself responsible for obtaining the client's consent and processing this data lawfully.`] },
        { heading: "6.4. Public authorities and legal requests", level: 3, paragraphs: ["Data may be provided in the cases and manner established by the legislation of the Republic of Azerbaijan — upon a reasoned written request of a court, investigative or other competent public authority. We check the legal basis of such a request and provide only the data required."] },
        { heading: "6.5. Business changes", level: 3, paragraphs: ["In the event of a merger, reorganisation of the company or transfer of the Platform to another person, data may pass to the new owner only on condition that the protections in this policy are maintained; you will be informed in advance."] },
        { heading: "7. Transfer of data outside Azerbaijan", paragraphs: [
          "The Platform's infrastructure runs on Cloudflare's global network; the database and file storage are kept in data centres in the European region, and requests may be processed in the Cloudflare data centre closest to you. Some service providers (see 6.2) are located in the USA and European Union countries. For this reason your data is transferred outside the Republic of Azerbaijan.",
          "Cross-border transfer is carried out in accordance with Article 14 of the Law \"On Personal Data\": data is transferred only to countries that ensure the protection of personal data or to providers that have contractually undertaken protection obligations, it is encrypted in transit (TLS), and its security is ensured by us. By registering on the Platform or submitting a form, you consent to this transfer. You may withdraw your consent at any time; in that case your account and enquiries are deleted (section 11).",
        ] },
        { heading: "8. Retention periods", intro: "We keep data only for as long as necessary to achieve the purpose; when the period ends, it is deleted or anonymised.", table: {
          columns: ["Data", "Retention period"],
          rows: [
            ["Account and profile", "while the account is active; after a deletion request it is deleted as described in section 11"],
            ["Listing", "while the listing is active; personal account listings live for 60 days and, if not renewed, expire and stop being publicly visible"],
            ["Enquiry, reservation, viewing request", "as long as necessary to provide the service, at most 3 years"],
            ["Session", "ends after 8 hours of inactivity or at the latest after 7 days"],
            ["Failed sign-in attempts", "90 days"],
            ["Security events", "180 days"],
            ["Known device record (hashed IP + device label)", "365 days"],
            ["Unique view keys", "2 days"],
            ["Verification document files", "deleted 30 days after the moderator's decision (the decision itself remains)"],
            ["Telegram bot events", "3 days; delivery log 30 days (message text is deleted immediately after sending)"],
            ["Closed support ticket (Telegram)", "90 days"],
            ["Admin panel audit log", "indefinitely for legal obligations and disputes (personal data minimised)"],
            ["Email and push subscription", "until you unsubscribe or the account is deleted"],
          ],
        } },
        { heading: "9. Data security", bullets: [
          { text: "All connections are encrypted with HTTPS (TLS)." },
          { text: "Passwords are stored as salted hashes using the PBKDF2-SHA256 algorithm." },
          { text: "Access to the admin panel requires mandatory two-step verification (TOTP, optionally a passkey); panel rights are role-based and follow the least-privilege principle." },
          { text: "After 5 failed attempts the account is locked for 15 minutes; forms are protected by Cloudflare Turnstile, rate limits and same-origin checks." },
          { text: "The session cookie carries only a signed identifier (HttpOnly, Secure); rights are checked against the database on every request, which allows access to be revoked immediately." },
          { text: "The two-step verification secret is stored in the database encrypted with AES-GCM." },
          { text: "Verification documents and report evidence are kept in private storage without public links; every view is logged." },
          { text: "You receive a security notification when you sign in from a new device." },
        ], paragraphs: [`No system is completely secure. If a data breach occurs, we will inform affected users and, where required by law, the competent public authority without delay. Never share your password; ${f.name} staff will never ask you for a password, SMS code or card details.`] },
        { id: LEGAL_ANCHORS.rights, heading: "10. Your rights", intro: "Under Article 7 of the Law \"On Personal Data\" you have the following rights:", bullets: [
          { label: "To be informed:", text: "to learn whether data about you exists and who the owner and operators are." },
          { label: "To demand justification:", text: "to learn the legal basis for collecting, processing and passing your data to third parties and its legal consequences for you." },
          { label: "Access:", text: "to see the content of the data collected about you, the purpose, period, methods and source of processing and the range of persons with access to it." },
          { label: "Rectification and erasure:", text: "to demand that inaccurate data be corrected and that data be destroyed, except where the law requires it to be kept." },
          { label: "Restriction and objection:", text: "to demand a ban on collecting and processing your data or to object to it (except where processing is mandatory by law)." },
          { label: "Objection to automated decisions:", text: "to object to a decision based solely on automated processing that affects your interests." },
          { label: "Protection:", text: "to demand that your data be protected." },
          { label: "Withdrawal of consent:", text: "to withdraw your consent at any time (this does not affect lawful processing before withdrawal)." },
          { label: "Complaint:", text: "to apply to the competent executive authority or a court if your rights are violated and to claim compensation for damage." },
        ] },
        { heading: "How to exercise your rights", level: 3, bullets: [
          { label: "1. Instantly in your account:", text: "in the \"Profile\" section you can change your data, download a copy of it with \"Export data\", turn off notification channels, unlink connected sign-in methods (Google, Apple, Facebook, Telegram) and delete your account." },
          { label: "2. By written request:", text: `in accordance with Article 7.5 of the Law, by submitting a written paper application together with an identity document at our office, or by sending a request signed with an enhanced electronic signature to ${f.securityEmail}. We also accept ordinary requests sent from your account's email address and act on them after verifying your identity.` },
        ], paragraphs: ["Requests are handled free of charge. A reply is given within 7 working days of receipt at the latest; if a third party must be contacted, this period may be extended by another 7 working days. If we refuse a request, a reasoned reply is sent within 5 working days. We inform any third party to whom we previously passed the data of a correction or restriction within 3 working days. Replies do not include other persons' personal data."] },
        { id: LEGAL_ANCHORS.dataDeletion, heading: "11. Deleting your account and data" },
        { heading: "11.1. Deleting from your account", level: 3, intro: "You can delete your account at any time via Account → \"Profile\" → \"Delete account\". Deletion takes two steps: first the account is deactivated immediately and sign-in is blocked, then your listings are archived and your personal data is deleted. If the second step is interrupted for technical reasons, the system retries it automatically.", bullets: [
          { text: "Listings belonging to an agency stay with the agency and pass to the agency owner; your personal listings are archived." },
          { text: "Reviews you wrote may be anonymised or deleted; enquiries other users sent to you may be retained to the extent required by law, as they are those users' right." },
          { text: "Records in the audit and security logs are kept until the periods in section 8 expire." },
        ] },
        { heading: "11.2. Accounts created with social sign-in (Google, Apple, Facebook, Telegram)", level: 3, intro: `If you opened your account with one of these providers, you can delete it as described in 11.1 — deletion also removes the provider identifier. To revoke ${f.name}'s access at the provider itself:`, bullets: [
          { label: "Facebook:", text: `Facebook → Settings & privacy → Settings → "Apps and websites" → ${f.name} → "Remove". If you then want the data received from Facebook deleted, delete your account in your Platform account or write to ${f.securityEmail} with the subject "Delete my Facebook data" — we complete the request and reply within 7 working days.` },
          { label: "Google:", text: `myaccount.google.com → Security → "Third-party apps & services" → ${f.name} → delete access.` },
          { label: "Apple:", text: `on iPhone, Settings → [your name] → "Sign in with Apple" → ${f.name} → "Stop using Apple ID".` },
          { label: "Telegram:", text: "unlink Telegram in your account or send /stop to the bot; deleting the chat with the bot in Telegram and blocking the bot is sufficient." },
        ] },
        { heading: "11.3. Enquiries sent without an account", level: 3, paragraphs: [`To delete an enquiry sent without an account, write to ${f.securityEmail} stating the email or phone number used in the enquiry.`] },
        { heading: "12. Notifications and marketing", bullets: [
          { text: "Service notifications about your account, security, listing moderation and enquiries are necessary for the Platform to work; security notifications cannot be turned off." },
          { text: "Matching listings, price drops and other informational notifications can be turned off by category and channel (site, email, Telegram) in Account → \"Notifications\" → \"Settings\"." },
          { text: "Telegram notifications are sent only after you link the bot to your account and explicitly enable notifications; signing in with Telegram is not consent to notifications." },
          { text: "We send promotional mass emails only with your separate consent; every email contains a way to opt out." },
        ] },
        { heading: "13. Cookies and similar technologies", paragraphs: ["The Platform uses cookies and browser storage that are necessary for it to work; analytics cookies are loaded only after your consent. See the Cookie policy for the full list, purposes and lifetimes."] },
        { heading: "14. Children's data", paragraphs: [`The Platform is not intended for persons under 18, and an account may only be opened by a person aged 18 or over. If we learn that data of a person under 18 has been passed to us, we delete it. If you are aware of such a case, write to ${f.securityEmail}.`] },
        { heading: "15. Third-party websites", paragraphs: ["The Platform links to WhatsApp, Telegram, maps, virtual tours (Kuula, Matterport, Momento360), state registers and partner websites. We are not responsible for the privacy rules of these sites; review their own policies before using them. A virtual tour loads only after you click it."] },
        { heading: "16. Changes to this policy", paragraphs: ["We may update this policy when the law, the Platform's features or service providers change. The updated text is published on this page and the date above changes. We give at least 10 days' notice on the site or by email before significant changes (a new purpose, a new data category, transfer to a new country) take effect. Continuing to use the Platform after a change means accepting the updated policy; if you do not agree, you can delete your account."] },
        { heading: "17. Contact", paragraphs: [contactLine] },
      ],
    },
    terms: {
      title: "Terms of use",
      metaDescription: "Registration, listing rules, moderation, additional services, limitation of liability and dispute resolution on the Luxe Home Estate platform.",
      description: "The rules that apply between you and Luxe Home Estate when you use the Platform.",
      updatedAt: "20 October 2026",
      introduction: `These Terms of use (the "Terms") govern the relationship between ${f.legalName} (TIN ${f.voen}, the "Company", "we") and any person (the "User", "you") using the luxehomeestate.az website, the personal account, the Telegram bot and related services (together — the "Platform"). Under the Civil Code of the Republic of Azerbaijan and the Law "On Electronic Commerce", the Terms are a contract of adhesion: by creating an account, posting a listing, sending an enquiry or otherwise using the Platform, you fully accept these Terms, the Privacy policy and the Cookie policy. If you do not agree, do not use the Platform.`,
      sections: [
        { heading: "1. Definitions", bullets: [
          { label: "Platform —", text: "the luxehomeestate.az website, all its subpages, the personal account, the admin panel, the Telegram bot, the API and mobile views." },
          { label: "User —", text: "any visitor of the Platform or account holder." },
          { label: "Account —", text: "the User's personal page on the Platform. Types: User (buyer/tenant), Property owner, Agent, Agency, Corporate (developer and other legal entities)." },
          { label: "Listing —", text: "information posted by a User on the Platform about the sale or rental of real estate." },
          { label: "Company listing —", text: `a listing posted by ${f.name} as part of its own agency service.` },
          { label: "Moderation —", text: "checking listings, reviews and profiles for compliance with these Terms." },
          { label: "Additional services —", text: "VIP, promotion, premium packages, subscription plans and other special features." },
          { label: "Content —", text: "text, photos, video, plans, links, reviews and other materials uploaded to the Platform." },
        ] },
        { heading: "2. Purpose of the Platform and role of the Company", bullets: [
          { label: "2.1.", text: "The Platform is an information service for posting and searching real estate listings and connecting buyers, sellers, tenants, property owners, agents and agencies. In addition, the Company provides agency (brokerage) services in its own name, for which a separate contract is concluded." },
          { label: "2.2.", text: "The Company is not a party to sale, rental, deposit, advance payment or other transactions between Users; it does not sell, buy or let property and does not charge a brokerage fee on Users' listings (Company listings excepted). The terms, payment and performance of a transaction are settled only between its parties." },
          { label: "2.3.", text: "The person who posted a User listing is responsible for the accuracy of its information (price, area, documents, ownership). Although the Company checks listings automatically and manually, it does not certify the legal and factual status of every listing. The \"Documents verified\" badge only means that a moderator has looked at the document submitted; it does not replace a notarial check or a check in the state register." },
          { label: "2.4.", text: "The price indicator, the \"Value my home\" estimate, mortgage and investment calculators, area statistics and Knowledge Hub materials are for information only; they are not a valuation report or legal, financial or tax advice." },
          { label: "2.5.", text: "Listings, prices and technical specifications are not a public offer." },
        ] },
        { heading: "3. Registration and account", bullets: [
          { label: "3.1.", text: "An account may only be opened by a person aged 18 or over with legal capacity, or by their authorised representative. A person opening an account on behalf of a legal entity confirms that they are authorised to do so." },
          { label: "3.2.", text: "Registration is done with email and password, Google, Apple, Facebook, Telegram or a verified phone number. You must provide accurate, complete and up-to-date information and update it in your account when it changes." },
          { label: "3.3.", text: "One person may hold one account per account type. Opening a new account to evade restrictions, or creating an account in someone else's name or with false information, is prohibited." },
          { label: "3.4.", text: "An agency account is opened with a TIN and appears as a public profile after approval by a moderator. A second active agency account cannot be opened with the same TIN. An agent may be an approved member of only one agency at a time." },
          { label: "3.5.", text: `You are responsible for the security of your account — protecting your password, email, phone and linked social accounts. If you suspect unauthorised use of your account, change your password immediately (this closes all sessions on other devices) and notify ${f.securityEmail}. Actions taken through your account are deemed to be yours, except in proven cases of unauthorised access.` },
        ] },
        { heading: "4. Listing rules", paragraphs: ["4.1. A listing may only be posted for real estate that actually exists and is offered for sale or rent. The person posting the listing must be the owner of the property, their authorised representative or an agent with written consent."] },
        { heading: "4.2. Listing requirements", level: 3, bullets: [
          { label: "Accuracy:", text: "the property's type, address, area, number of rooms, floor, renovation, documents and price must reflect reality." },
          { label: "One property — one listing:", text: "posting duplicate listings for the same property or repeating the same listing in different categories or cities is prohibited." },
          { label: "Price:", text: "the full price of the property must be stated; search results must not be distorted with a symbolic (e.g. 1 AZN), conditional or \"negotiable\" price. For rentals, the payment period (daily, monthly) must be chosen correctly." },
          { label: "Photos:", text: "only real, current photos of that property; images taken from another listing, the internet or bearing someone else's watermark, collages, and phone numbers, logos or advertising on images are prohibited. The Platform's watermark is added to uploaded images." },
          { label: "Text:", text: "the description must not contain phone numbers, email addresses, external links, advertising of other services, text in capital letters or text unrelated to the property. Contact details are shown only in the field reserved for them." },
          { label: "Seller type:", text: "an owner must present themselves as the owner and an agent as an agent. An agent presenting a listing as an owner's listing is prohibited." },
          { label: "Availability:", text: "it must be possible to reach the number shown in the listing; if the property has been sold or let, the listing must be closed immediately as \"Sold / Rented\" or deleted." },
        ] },
        { heading: "4.3. Prohibited listings", level: 3, paragraphs: [
          "Non-existent or \"bait\" listings with an attractive price; property whose state registration is not permitted by law or whose legal restrictions are concealed (in certain cases an explicit note to that effect is required); listings demanding a deposit or advance payment before a viewing; goods and services unrelated to real estate; discriminatory conditions (refusal based on nationality, religion, sex, etc.); any content prohibited by law.",
          "4.4. A personal account listing lives for 60 days (the Company may change this period); a reminder is sent before it expires, and the period can be extended with the \"Renew\" button in the account.",
        ] },
        { heading: "5. Moderation, restrictions and appeals", bullets: [
          { label: "5.1.", text: "Listings may be checked automatically and manually before or after publication. The Company has the right to return a listing that breaches the Terms for correction (\"Changes requested\"), reject, suspend, remove from public view or delete it. The reason for the decision is shown in the account." },
          { label: "5.2.", text: "Where the Terms are breached, or in case of a fake listing, suspected fraud, an upheld report or a threat to account security, the Company may warn the account, reduce its listing limit, require additional verification, temporarily suspend or block the account. Measures are applied with a justification and you are notified." },
          { label: "5.3.", text: "You can appeal from your account against the rejection or suspension of a listing, as well as against a restriction applied to your account. The appeal is reviewed by a staff member other than the one who made the decision. If the appeal is upheld, the measure is lifted; if rejected, the reason is given." },
          { label: "5.4.", text: "Moderation does not make the Company responsible for the accuracy of listings and does not guarantee that every breach will be detected immediately." },
        ] },
        { heading: "6. Reports and reviews", bullets: [
          { label: "6.1.", text: "Every public listing and review has a \"Report\" function. Submit reports only in good faith and on real grounds; false reports aimed at taking down a competitor's listing may lead to restrictions on the account. Signed-in users are notified of the outcome of their report." },
          { label: "6.2.", text: "Only a user with a verified email or phone may review an agent or agency; one review per target. A review must be based on real experience and must not contain insults, personal data, advertising or false claims. Agents and agencies may not review themselves, order fake reviews or offer benefits in exchange for reviews. The Company moderates reviews and may decline to publish or hide reviews that break the rules." },
        ] },
        { heading: "7. Special terms for agency and agent accounts", bullets: [
          { label: "7.1.", text: "An agency is responsible for its agents' actions on the Platform, the rights it grants them and the composition of its team. A listing posted on behalf of an agency belongs to the agency's workspace; when an agent leaves the agency these listings stay with the agency, while the agent's personal listings stay with the agent." },
          { label: "7.2.", text: "An agency routes enquiries to agents according to its distribution rule; a client's contact details may be used only for the purpose of that enquiry. When an agent leaves the agency, open enquiries and CRM cards assigned to them return to the agency." },
          { label: "7.3.", text: "Agents and agencies who enter third parties' data in the CRM are themselves responsible for obtaining those persons' consent, processing the data in accordance with the Law \"On Personal Data\" and not sending spam." },
          { label: "7.4.", text: "A listing may be transferred from one agency to another only with the consent of the current agency and the property owner and the approval of a moderator." },
        ] },
        { heading: "8. Additional services (VIP, promotion, packages, subscription)", bullets: [
          { label: "8.1.", text: "The content, duration and price (if any) of additional services are shown on the Platform or in the order confirmation before ordering. Online card payments are not currently accepted on the Platform; fees for paid services are paid at the Company's office or by bank transfer, and a payment document is issued." },
          { label: "8.2.", text: "VIP status and promotion increase a listing's visibility but do not guarantee a certain number of views, enquiries or a completed transaction." },
          { label: "8.3.", text: `If an additional service was applied to a listing that breaches the Terms and the listing was suspended by a moderation decision, no refund is given for the remaining period. The value of a service not delivered for technical reasons is refunded pro rata for the remaining period, or the period is extended. A refund request must be sent in writing to ${f.financeEmail} within 14 days after the service ends.` },
          { label: "8.4.", text: "The terms of subscription plans (limits, trial period, renewal and cancellation) will be set out in a separate offer when online payment becomes available." },
        ] },
        { heading: "9. Prohibited conduct", intro: "The following is prohibited on the Platform:", bullets: [
          { text: "impersonating another person (including the Company, a public authority or a well-known agency);" },
          { text: "fraud, demanding a deposit or advance payment before a viewing, submitting forged documents;" },
          { text: "collecting or selling contact details obtained from the Platform or using them for mass mailing or calls;" },
          { text: "harvesting content with bots, scrapers, automated requests or other means, or bypassing rate limits, Turnstile and other protection mechanisms;" },
          { text: `probing the Platform's security, exploiting vulnerabilities, uploading malicious code (if you find a security vulnerability, report it to ${f.securityEmail});` },
          { text: "insults, threats, hate speech, discrimination, publishing another person's personal data without permission;" },
          { text: "infringing intellectual property rights;" },
          { text: "any other act contrary to the legislation of the Republic of Azerbaijan." },
        ] },
        { heading: "10. Intellectual property", bullets: [
          { label: "10.1.", text: `The Platform's design, software code, texts, Knowledge Hub materials, database structure, logo and the "Luxe Home Estate" brand belong to ${f.ownerName} and/or the Company and are protected by law. Copying, distributing, modifying or using them commercially without written permission is prohibited.` },
          { label: "10.2.", text: "You retain the copyright in the content you upload. By uploading content you grant the Company a free, non-exclusive, worldwide licence, for as long as the listing or account is active (and a reasonable additional period for technical backups), to display it on the Platform, its mobile views, social media pages and search and sharing previews, to add a watermark, resize and translate it." },
          { label: "10.3.", text: `You warrant that the content you upload does not infringe third-party rights. If you believe your rights have been infringed, write to ${f.email} with the link and evidence; the content will be reviewed without delay.` },
        ] },
        { heading: "11. Limitation of liability", bullets: [
          { label: "11.1.", text: "The Platform is provided \"as is\". The Company makes reasonable efforts for it to operate without interruption or errors, but is not liable for interruptions caused by maintenance, failures of third-party providers (hosting, email, SMS, social sign-in), cyberattacks or force majeure." },
          { label: "11.2.", text: "The Company is not liable for: the content of User listings and reviews; transactions concluded between Users and their performance; loss of deposits, advances or other amounts paid; the content of third-party websites; decisions based on calculators and price indicators." },
          { label: "11.3.", text: "To the extent permitted by law, the Company's liability for any claim is limited to the amount the User paid the Company for additional services in the 12 months preceding the claim. This limitation does not apply to damage caused intentionally or through gross negligence, or to liability that cannot be limited by law." },
          { label: "11.4.", text: "The User is liable under the law for damage caused to the Company or third parties as a result of breaching these Terms." },
        ] },
        { heading: "12. Recommendations for a safe transaction", bullets: [
          { text: "Do not pay any amount (deposit, advance, \"reservation fee\") without viewing the property in person and checking the documents." },
          { text: "Verify ownership with an extract from the register of the State Service on Property Issues; formalise the transaction through a notary." },
          { text: "Pay by bank transfer and get a receipt; never give card details, SMS codes or passwords to people you do not know." },
          { text: "Report suspicious listings with the \"Report this listing\" function. A detailed guide is available in the Knowledge Hub." },
        ] },
        { heading: "13. Term and termination", bullets: [
          { label: "13.1.", text: "The Terms take effect when you start using the Platform and remain in force while your account exists." },
          { label: "13.2.", text: "You may terminate the contract at any time by deleting your account (Privacy policy, section 11)." },
          { label: "13.3.", text: "The Company may close an account in the event of serious or repeated breaches of the Terms, suspected unlawful activity or long inactivity (more than 24 months); where possible, notice is given in advance." },
          { label: "13.4.", text: "Provisions on intellectual property, liability, dispute resolution and obligations that arose before termination survive termination." },
        ] },
        { heading: "14. Notices and electronic communication", paragraphs: [`The Company sends legal and service notices to the email in your account, to your account or to another channel you have consented to; such notices are deemed written notices. Legal notices to the Company are sent to ${f.address} or to ${f.email}.`] },
        { heading: "15. Governing law and dispute resolution", bullets: [
          { label: "15.1.", text: "These Terms are governed by the legislation of the Republic of Azerbaijan." },
          { label: "15.2.", text: `Disputes are first resolved through negotiation: send your claim to ${f.email} and we will reply within 30 days. If no agreement is reached, the dispute is settled by the competent court of Baku in accordance with the legislation of the Republic of Azerbaijan. This provision does not limit the rights granted to you by law as a consumer.` },
        ] },
        { heading: "16. Changes to the Terms", paragraphs: ["The Company may change the Terms. The updated text is published on this page and its date changes; at least 10 days' notice is given on the site or by email of significant changes affecting your rights and obligations. Continuing to use the Platform after a change takes effect means accepting the new Terms."] },
        { heading: "17. Final provisions", paragraphs: ["If any provision of the Terms is held invalid, the remaining provisions remain in force. The Company's failure to exercise a right is not a waiver of that right. The Terms are published in Azerbaijani, English and Russian; in case of discrepancy, the Azerbaijani text prevails."] },
        { heading: "18. Contact", paragraphs: [`${f.legalName} · TIN ${f.voen} · ${f.address} · ${f.email} · ${f.supportEmail} · ${f.phone}`] },
      ],
    },
    cookies: {
      title: "Cookie policy",
      metaDescription: "Cookies and browser storage used on the Luxe Home Estate website, their purpose, lifetime and how you can manage your consent.",
      description: "Which cookies the site uses, how long they are kept and how you can manage your choice.",
      updatedAt: "20 October 2026",
      introduction: "This policy explains which cookies and similar technologies the luxehomeestate.az website (the \"Site\") uses in your browser, why they are needed, how long they are kept and how you can manage your choice. It forms part of the Privacy policy. Our principle is simple: no non-essential cookie is set without your consent.",
      sections: [
        { heading: "1. What is a cookie", intro: "A cookie is a small text file that a website stores in your browser. It is sent back to the site with the next request and lets the site recognise you (for example, remember that you are signed in). Cookies may be:", bullets: [
          { label: "Session cookie —", text: "deleted when the browser closes;" },
          { label: "Persistent cookie —", text: "kept for a set period or until deleted;" },
          { label: "First-party cookie —", text: "set by luxehomeestate.az;" },
          { label: "Third-party cookie —", text: "set by another domain (for example, Google)." },
        ], paragraphs: ["Similar technologies: browser storage (localStorage and sessionStorage) works like cookies but does not send data to the server automatically. The Site uses them too, and this policy applies to them as well."] },
        { heading: "2. Cookie categories", bullets: [
          { label: "Strictly necessary —", text: "for sign-in, security, bot protection and remembering your choice. The Site does not work without them, so they require no consent and cannot be switched off." },
          { label: "Functional (preferences) —", text: "convenience features such as theme, favourites and recently viewed. Stored only on your device and carry no personal data." },
          { label: "Analytics —", text: "to measure how the Site is used (Google Analytics / Google Tag Manager). Loaded only after your explicit consent." },
          { label: "Advertising / marketing —", text: "the Site does not use advertising or tracking cookies and does not pass data to advertising networks." },
        ] },
        { heading: "3. Cookies we use" },
        { heading: "3.1. Strictly necessary cookies (first party)", level: 3, table: {
          columns: ["Name", "Purpose", "Lifetime"],
          codeFirstColumn: true,
          rows: [
            ["lhe_session", "signed session identifier of a signed-in user", "until the session ends (8 hours of inactivity, at most 7 days)"],
            ["lhe_2fa", "second verification step of staff sign-in", "a few minutes"],
            ["lhe_webauthn", "one-time check for passkey sign-in", "5 minutes"],
            ["lhe_oauth", "security check for Sign in with Google (state, PKCE, nonce)", "10 minutes"],
            ["lhe_apple_oauth", "security check for Sign in with Apple", "10 minutes"],
            ["lhe_fb_oauth", "security check for Facebook Login", "10 minutes"],
            ["lhe_tg_oauth", "security check for Sign in with Telegram", "10 minutes"],
            ["lhe_tg_pending", "while a Telegram sign-up awaits confirmation", "15 minutes"],
            ["lhe_apple_oauth_link, lhe_fb_oauth_link, etc.", "passing the result when linking a sign-in method from the account", "2 minutes"],
            ["analytics_consent", "remembering your analytics choice (accept / decline)", "1 year"],
          ],
        }, paragraphs: ["All authentication cookies are HttpOnly (JavaScript cannot read them), Secure (HTTPS only) and SameSite-protected and carry only a signed identifier — your name, email or password is never written to a cookie."] },
        { heading: "3.2. Strictly necessary cookies (Cloudflare)", level: 3, table: {
          columns: ["Name", "Purpose", "Lifetime"],
          codeFirstColumn: true,
          rows: [
            ["__cf_bm", "distinguishing bots from real visitors", "30 minutes"],
            ["cf_clearance", "remembering that you passed a security check (only when a check is shown)", "usually 30 minutes – 1 day"],
            ["Turnstile (challenges.cloudflare.com)", "bot protection of forms — sign-in, registration, contact and report forms", "duration of the check"],
          ],
        }, paragraphs: ["Cloudflare Web Analytics does not use cookies and does not track you across sites."] },
        { heading: "3.3. Functional — browser storage (localStorage)", level: 3, table: {
          columns: ["Key", "Purpose", "Lifetime"],
          codeFirstColumn: true,
          rows: [
            ["theme, lhe-theme-synced", "light / dark theme choice", "until deleted"],
            ["luxehomeestate:favorites", "favourite listings chosen as a guest (moved to your account when you sign in)", "until deleted"],
            ["luxehomeestate:recently-viewed", "listings you viewed recently", "until deleted"],
            ["luxehomeestate:compare", "comparison list", "until deleted"],
            ["listing form draft", "filled-in fields of a new listing form — so they are not lost if the page closes by accident", "until submitted or deleted"],
            ["sessionStorage keys", "reload guard when a new version is deployed", "until the tab closes"],
          ],
        } },
        { heading: "3.4. Analytics (consent only, third party — Google)", level: 3, table: {
          columns: ["Name", "Purpose", "Lifetime"],
          codeFirstColumn: true,
          rows: [
            ["_ga", "distinguishing visitors with an anonymous identifier", "2 years"],
            ["_ga_<ID>", "keeping the session state", "2 years"],
            ["_gid", "distinguishing daily visitors", "24 hours"],
          ],
        }, paragraphs: ["Analytics events do not include phone numbers, emails, names, addresses or enquiry text. The data is processed by Google LLC (Google's privacy policy: policies.google.com/privacy)."] },
        { heading: "3.5. Cookies we do not set", level: 3, paragraphs: ["The Site does not set a cookie for the language choice — the language is kept in the URL (/az, /en, /ru). Facebook Pixel, advertising remarketing and similar tracking tools are not used."] },
        { heading: "3.6. External content", level: 3, paragraphs: ["Virtual tours (Kuula, Matterport, Momento360) that load when you click them, WhatsApp and Telegram links and map services may set their own cookies. These cookies are subject to those services' policies; a virtual tour does not load until you open it."] },
        { id: LEGAL_ANCHORS.consent, heading: "4. Managing consent", bullets: [
          { text: "On your first visit a choice panel about analytics is shown: the \"Allow analytics\" and \"Decline\" buttons are equally prominent; if you keep using the Site without choosing, analytics is not loaded." },
          { text: "You can change your choice at any time with the \"Cookie settings\" button at the bottom of the Site or below this section." },
          { text: "When you withdraw consent, analytics stops immediately and analytics cookies (_ga, _ga_<ID>, _gid) are deleted from your browser." },
          { text: "Your choice is kept in the analytics_consent cookie for 1 year; you are asked again when it expires or when you delete cookies." },
          { text: "Consent is given separately for each browser and device." },
        ] },
        { heading: "5. Managing cookies in your browser", intro: "You can delete or block cookies and browser storage in your browser settings:", bullets: [
          { label: "Chrome:", text: "Settings → Privacy and security → Third-party cookies / Site data;" },
          { label: "Safari:", text: "Settings → Privacy → Manage Website Data;" },
          { label: "Firefox:", text: "Settings → Privacy & Security → Cookies and Site Data;" },
          { label: "Edge:", text: "Settings → Cookies and site permissions." },
        ], paragraphs: ["If you block strictly necessary cookies, sign-in, the account area and forms may not work. Favourites can be deleted with \"Clear list\" on the \"Favourites\" page and recently viewed listings with the corresponding button in your account. To opt out of analytics on all websites, you can also use Google's official \"Google Analytics Opt-out\" browser add-on."] },
        { heading: "6. Changes", paragraphs: ["This policy is updated and its date changes when a new cookie or service is added. If a new category (for example, a new analytics tool) is added, your consent will be asked for again before it is used."] },
        { heading: "7. Contact", paragraphs: [`For questions: ${f.securityEmail} · ${f.email} · ${f.phone}`] },
      ],
    },
  };
}
